"""Renders generated Python source."""

from __future__ import annotations

import re
from typing import Any

from .naming import BUILTIN_NAMES, docstring, safe_identifier, snake
from .operations import Operation, Param, Resource, python_path
from .schemas import AliasDecl, ClassDecl, GenerationError, TypeRegistry

HEADER = (
    "# This file is generated by `python -m codegen` from spec/contract.json. Do not edit it by hand.\n"
    "# OpenCode {version}\n"
)

_IDENTIFIER = re.compile(r"\b[A-Za-z_][A-Za-z0-9_]*\b")

STATUS_BASES = {
    400: "BadRequestError",
    401: "AuthenticationError",
    403: "PermissionDeniedError",
    404: "NotFoundError",
    409: "ConflictError",
    413: "ContentTooLargeError",
    422: "UnprocessableEntityError",
    429: "RateLimitError",
    500: "InternalServerError",
    501: "NotImplementedServerError",
    503: "ServiceUnavailableError",
}


def _names_in(expr: str) -> set[str]:
    return set(_IDENTIFIER.findall(expr))


# -- types --------------------------------------------------------------------------------------------------


def _field_line(field_decl: Any) -> str:
    annotation = field_decl.type
    if (field_decl.nullable or not field_decl.required) and annotation != "Any":
        annotation = f"{annotation} | None"
    args: list[str] = []
    if field_decl.wire != field_decl.name:
        args.append(f"validation_alias={field_decl.wire!r}")
        args.append(f"serialization_alias={field_decl.wire!r}")
    if field_decl.literal_default is not None and field_decl.required:
        default: str | None = field_decl.literal_default
    elif not field_decl.required:
        default = "None"
        if not field_decl.nullable:
            args.append("exclude_if=is_none")
    else:
        default = None
    if args:
        inner = ", ".join(([f"default={default}"] if default is not None else []) + args)
        return f"    {field_decl.name}: {annotation} = Field({inner})"
    if default is not None:
        return f"    {field_decl.name}: {annotation} = {default}"
    return f"    {field_decl.name}: {annotation}"


def render_class(decl: ClassDecl) -> str:
    lines = [f"class {decl.name}(BaseModel):"]
    doc = docstring(decl.doc, "    ")
    if doc:
        lines.append(doc)
        lines.append("")
    always_set = [field.name for field in decl.fields if field.literal_default is not None and field.required]
    if always_set:
        lines.append(f"    __opencode_always_set__: ClassVar[tuple[str, ...]] = {tuple(always_set)!r}")
        lines.append("")
    if not decl.fields and not doc:
        lines.append("    pass")
    for field_decl in decl.fields:
        lines.append(_field_line(field_decl))
        field_doc = docstring(field_decl.doc, "    ")
        if field_doc:
            lines.append(field_doc)
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def render_alias(decl: AliasDecl) -> str:
    lines = [f"{decl.name}: TypeAlias = {decl.expr}"]
    doc = docstring(decl.doc, "")
    if doc:
        lines.append(doc)
    return "\n".join(lines) + "\n"


def _alias_order(aliases: dict[str, AliasDecl]) -> list[AliasDecl]:
    names = set(aliases)
    deps = {name: (_names_in(decl.expr) & names) - {name} for name, decl in aliases.items()}
    ordered: list[AliasDecl] = []
    state: dict[str, int] = {}

    def visit(name: str, chain: list[str]) -> None:
        if state.get(name) == 2:
            return
        if state.get(name) == 1:
            raise GenerationError(f"Alias cycle: {' -> '.join([*chain, name])}")
        state[name] = 1
        for dep in sorted(deps[name]):
            visit(dep, [*chain, name])
        state[name] = 2
        ordered.append(aliases[name])

    for name in sorted(aliases):
        visit(name, [])
    return ordered


def render_types(registry: TypeRegistry, version: str) -> str:
    out = [
        HEADER.format(version=version),
        '"""Models for every OpenCode API type.\n\n'
        "Each class mirrors a schema of the OpenCode server. Attributes are snake_case; the wire names are kept\n"
        'as aliases, so models validate server JSON and serialize back to it unchanged.\n"""\n',
        "from __future__ import annotations\n",
        "from typing import Annotated, Any, ClassVar, Literal, TypeAlias\n",
        "from pydantic import Discriminator, Field, Tag\n",
        "from .._models import BaseModel, is_none",
        "from .._types import OpenEnum",
        "from .._unions import discriminator\n\n",
    ]
    for name in sorted(registry.classes):
        out.append(render_class(registry.classes[name]))
        out.append("\n")
    for alias in _alias_order(registry.aliases):
        out.append(render_alias(alias))
        out.append("\n")
    exported = sorted([*registry.classes, *registry.aliases])
    out.append("__all__ = [\n" + "".join(f"    {name!r},\n" for name in exported) + "]\n")
    return "\n".join(out)


def render_types_init(registry: TypeRegistry, version: str) -> str:
    exported = sorted([*registry.classes, *registry.aliases])
    lines = [
        HEADER.format(version=version),
        '"""Typed models for OpenCode API requests, responses and events."""\n',
        "from __future__ import annotations\n",
        "from ._generated import (",
        *[f"    {name} as {name}," for name in exported],
        ")\n",
        "__all__ = [",
        *[f"    {name!r}," for name in exported],
        "]\n",
    ]
    return "\n".join(lines)


# -- errors -------------------------------------------------------------------------------------------------


def error_classes(operations: list[Operation], registry: TypeRegistry) -> dict[str, dict[str, Any]]:
    """Collects one entry per server error tag: class name, base class and body model."""
    tags: dict[str, dict[str, Any]] = {}
    for operation in operations:
        for error in operation.errors:
            if error.tag is None:
                continue
            body = registry.type_of(error.schema, context=f"{error.tag}Body").expr
            entry = tags.setdefault(error.tag, {"statuses": set(), "body": body})
            entry["statuses"].add(error.status)
            if entry["body"] != body:
                raise GenerationError(f"Error tag {error.tag} has different bodies: {entry['body']} / {body}")
    result: dict[str, dict[str, Any]] = {}
    for tag, entry in sorted(tags.items()):
        statuses = sorted(entry["statuses"])
        if len(statuses) != 1:
            raise GenerationError(f"Error tag {tag} is declared with several statuses: {statuses}")
        status = statuses[0]
        base = STATUS_BASES.get(status) or ("InternalServerError" if status >= 500 else "APIStatusError")
        class_name = tag if tag not in BUILTIN_NAMES else f"Remote{tag}"
        result[tag] = {
            "class": class_name,
            "base": base,
            "status": status,
            "body": entry["body"],
            "is_base": tag == base,
        }
    return result


def render_errors(errors: dict[str, dict[str, Any]], version: str) -> str:
    bases = sorted(
        {entry["base"] for entry in errors.values()} | {entry["class"] for entry in errors.values() if entry["is_base"]}
    )
    bodies = sorted({entry["body"] for entry in errors.values()})
    lines = [
        HEADER.format(version=version),
        '"""Errors the OpenCode server declares, keyed by their ``_tag``."""\n',
        "from __future__ import annotations\n",
        "from typing import TYPE_CHECKING\n",
        "from ._exceptions import (",
        "    APIStatusError,",
        *[f"    {name}," for name in bases if name != "APIStatusError"],
        ")\n",
        "if TYPE_CHECKING:",
        "    from .types import (",
        *[f"        {name}," for name in bodies],
        "    )\n",
        "__all__ = [",
        '    "TAGGED_ERRORS",',
        *[f"    {entry['class']!r}," for entry in errors.values() if not entry["is_base"]],
        "]\n\n",
    ]
    for tag, entry in errors.items():
        if entry["is_base"]:
            continue
        lines.append(f"class {entry['class']}({entry['base']}):")
        lines.append(f'    """The server answered {entry["status"]} with ``_tag`` ``{tag}``."""\n')
        lines.append(f"    tag = {tag!r}\n")
        lines.append("    @property")
        lines.append(f'    def error(self) -> "{entry["body"]}":')
        lines.append('        """The error body as a typed model."""')
        lines.append(f"        from .types import {entry['body']}\n")
        lines.append(f"        return self._typed_body({entry['body']})\n\n")
    lines.append("TAGGED_ERRORS: dict[str, type[APIStatusError]] = {")
    for tag, entry in errors.items():
        lines.append(f"    {tag!r}: {entry['class']},")
    lines.append("}\n")
    return "\n".join(lines)


# -- resources ----------------------------------------------------------------------------------------------


def _resource_type(expr: str) -> str:
    """Qualifies ``list`` / ``dict`` so a method named ``list`` cannot shadow them in annotations."""
    return re.sub(r"(?<![\w.])(list|dict)\[", r"builtins.\1[", expr)


def _input_type(param: Param) -> str:
    expr = param.type
    if expr.startswith("list["):
        expr = "Sequence[" + expr[len("list[") :]
    elif expr.startswith("dict[str, "):
        expr = "Mapping[str, " + expr[len("dict[str, ") :]
    expr = _resource_type(expr)
    if param.nullable:
        expr = f"{expr} | None"
    if not param.required:
        expr = f"{expr} | NotGiven"
    return expr


def _method_doc(operation: Operation, errors: dict[str, dict[str, Any]], indent: str) -> str:
    parts: list[str] = []
    if operation.summary:
        parts.append(operation.summary.rstrip(".") + ".")
    if operation.description:
        parts.append(operation.description)
    notes: list[str] = []
    if operation.experimental:
        notes.append("This endpoint is experimental in OpenCode and may change without notice.")
    if operation.deprecated:
        notes.append("Deprecated.")
    if notes:
        parts.append(" ".join(notes))
    documented = [param for param in operation.params if param.doc]
    if documented:
        parts.append("Args:\n" + "\n".join(f"  {param.name}: {_one_line(param.doc or '')}" for param in documented))
    raised = []
    for error in operation.errors:
        if error.tag and error.tag in errors:
            name = errors[error.tag]["class"]
            if name not in raised:
                raised.append(name)
    if raised:
        parts.append("Raises:\n" + "\n".join(f"  {name}" for name in raised))
    parts.append(f"``{operation.http_method} {operation.path}``")
    return docstring("\n\n".join(parts), indent) or ""


def _one_line(text: str) -> str:
    return " ".join(text.split())


def _render_method(operation: Operation, errors: dict[str, dict[str, Any]], *, is_async: bool) -> list[str]:
    args = ["        self,"]
    for param in operation.path_params:
        args.append(f"        {param.name}: {_input_type(param)},")
    args.append("        *,")
    required = [param for param in operation.keyword_params if param.required]
    optional = [param for param in operation.keyword_params if not param.required]
    for param in [*required, *optional]:
        default = "" if param.required else " = NOT_GIVEN"
        args.append(f"        {param.name}: {_input_type(param)}{default},")
    args += [
        "        extra_headers: Headers | None = None,",
        "        extra_query: Query | None = None,",
        "        extra_body: Body | None = None,",
        "        timeout: Timeout | NotGiven = NOT_GIVEN,",
    ]

    return_type = _resource_type(operation.return_type)
    if operation.kind == "page":
        returns = f"{'AsyncPaginator' if is_async else 'SyncCursorPage'}[{return_type}]"
    elif operation.kind == "stream":
        returns = f"{'AsyncStream' if is_async else 'Stream'}[{return_type}]"
    else:
        returns = return_type

    define = "async def" if is_async and operation.kind != "page" else "def"
    lines = [f"    {define} {operation.method_name}(", *args, f"    ) -> {returns}:"]
    doc = _method_doc(operation, errors, "        ")
    if doc:
        lines.append(doc)

    options = [f'            method="{operation.http_method}",', f'            path=f"{python_path(operation)}",']
    query = [param for param in operation.params if param.source == "query"]
    headers = [param for param in operation.params if param.source == "headers"]
    payload = [param for param in operation.params if param.source == "payload"]
    if query:
        entries = []
        for param in query:
            value = f"self._location({param.name})" if param.wire == "location" else param.name
            entries.append(f"{param.wire!r}: {value}")
        options.append("            query={" + ", ".join(entries) + "},")
    if headers:
        options.append("            headers={" + ", ".join(f"{param.wire!r}: {param.name}" for param in headers) + "},")
    if payload:
        if operation.payload_mode == "binary":
            options.append(f"            content=bytes({payload[0].name}),")
        elif operation.payload_mode == "opaque":
            options.append(f"            body={payload[0].name},")
        else:
            options.append(
                "            body={" + ", ".join(f"{param.wire!r}: {param.name}" for param in payload) + "},"
            )
    options += [
        "            extra_headers=extra_headers,",
        "            extra_query=extra_query,",
        "            extra_body=extra_body,",
        "            timeout=timeout,",
    ]
    request_options = ["            RequestOptions(", *[f"    {line}" for line in options], "            ),"]

    awaiting = "await " if is_async else ""
    if operation.kind == "page":
        lines += [
            "        return self._client.page(",
            *request_options,
            f"            response_type={_resource_type(operation.response_type or 'Any')},",
            "        )",
        ]
    elif operation.kind == "stream":
        lines += [
            f"        return {awaiting}self._client.stream(",
            *request_options,
            f"            item_type={_resource_type(operation.response_type or 'Any')},",
            "        )",
        ]
    elif operation.kind == "void":
        lines += [f"        {awaiting}self._client.request(", *request_options, '            kind="void",', "        )"]
    elif operation.kind == "binary":
        lines += [
            f'        return cast("bytes", {awaiting}self._client.request(',
            *request_options,
            '            kind="binary",',
            "        ))",
        ]
    else:
        lines += [
            f"        return cast({returns!r}, {awaiting}self._client.request(",
            *request_options,
            f"            response_type={_resource_type(operation.response_type or 'Any')},",
            *(["            unwrap=True,"] if operation.unwrap else []),
            "        ))",
        ]
    return lines


def _resource_classes(resource: Resource, errors: dict[str, dict[str, Any]], *, is_async: bool) -> list[str]:
    blocks: list[str] = []
    for child in resource.children.values():
        blocks += _resource_classes(child, errors, is_async=is_async)
    prefix = "Async" if is_async else ""
    base = "AsyncAPIResource" if is_async else "SyncAPIResource"
    lines = [f"class {prefix}{resource.class_name}Resource({base}):"]
    title = ".".join(resource.path)
    lines.append(f'    """Operations under ``client.{_attr_path(resource)}`` (OpenCode ``{title}``)."""\n')
    for name, child in resource.children.items():
        lines += [
            "    @cached_property",
            f"    def {name}(self) -> {prefix}{child.class_name}Resource:",
            f"        return {prefix}{child.class_name}Resource(self._client)\n",
        ]
    for operation in resource.operations:
        lines += _render_method(operation, errors, is_async=is_async)
        lines.append("")
    blocks.append("\n".join(lines).rstrip() + "\n")
    return blocks


def _attr_path(resource: Resource) -> str:
    return ".".join(safe_identifier(snake(part)) for part in resource.path)


def _collect_type_names(resource: Resource, known: set[str]) -> set[str]:
    names: set[str] = set()
    for operation in resource.operations:
        for param in operation.params:
            names |= _names_in(param.type) & known
        names |= _names_in(operation.return_type) & known
        if operation.response_type:
            names |= _names_in(operation.response_type) & known
    for child in resource.children.values():
        names |= _collect_type_names(child, known)
    return names


def _all_operations(resource: Resource) -> list[Operation]:
    items = list(resource.operations)
    for child in resource.children.values():
        items += _all_operations(child)
    return items


def render_resource_module(
    resource: Resource, registry: TypeRegistry, errors: dict[str, dict[str, Any]], version: str
) -> str:
    known = set(registry.classes) | set(registry.aliases)
    type_names = sorted(_collect_type_names(resource, known))
    operations = _all_operations(resource)
    source = "\n".join(
        [*_resource_classes(resource, errors, is_async=False), *_resource_classes(resource, errors, is_async=True)]
    )
    uses = _names_in(source)
    typing_names = sorted({"Any", "Literal", "cast"} & uses)
    abc_names = sorted({"Mapping", "Sequence"} & uses)
    runtime: list[str] = []
    if "encode_path_segment" in uses:
        runtime.append("encode_path_segment")
    if "encode_path" in uses:
        runtime.append("encode_path")
    lines = [
        HEADER.format(version=version),
        f'"""The ``{resource.name}`` resource."""\n',
        "from __future__ import annotations\n",
        "import builtins" if "builtins" in uses else "",
        *([f"from collections.abc import {', '.join(abc_names)}"] if abc_names else []),
        "from functools import cached_property" if "cached_property" in uses else "",
        *([f"from typing import {', '.join(typing_names)}"] if typing_names else []),
        "",
        "from .._base_client import RequestOptions",
        *(
            ["from .._pagination import AsyncPaginator, SyncCursorPage"]
            if any(op.kind == "page" for op in operations)
            else []
        ),
        *([f"from .._qs import {', '.join(runtime)}"] if runtime else []),
        "from .._resource import AsyncAPIResource, SyncAPIResource",
        *(["from .._streaming import AsyncStream, Stream"] if any(op.kind == "stream" for op in operations) else []),
        "from .._types import NOT_GIVEN, Body, Headers, NotGiven, Query, Timeout"
        + (", OpenEnum" if "OpenEnum" in uses else ""),
        *(["from ..types import (", *[f"    {name}," for name in type_names], ")"] if type_names else []),
        "",
        f"__all__ = [{', '.join(repr(prefix + resource.class_name + 'Resource') for prefix in ('', 'Async'))}]\n\n",
        source,
    ]
    return "\n".join(line for line in lines if line is not None)


def render_resources_init(resources: dict[str, Resource], version: str) -> str:
    imports = []
    sync_props = []
    async_props = []
    for name, resource in sorted(resources.items()):
        module = name
        imports.append(f"from .{module} import Async{resource.class_name}Resource, {resource.class_name}Resource")
        sync_props += [
            "    @cached_property",
            f"    def {name}(self) -> {resource.class_name}Resource:",
            f'        """Operations for OpenCode ``{resource.path[0]}``."""',
            f'        return {resource.class_name}Resource(cast("Opencode", self))\n',
        ]
        async_props += [
            "    @cached_property",
            f"    def {name}(self) -> Async{resource.class_name}Resource:",
            f'        """Operations for OpenCode ``{resource.path[0]}``."""',
            f'        return Async{resource.class_name}Resource(cast("AsyncOpencode", self))\n',
        ]
    lines = [
        HEADER.format(version=version),
        '"""Resource groups attached to the clients."""\n',
        "from __future__ import annotations\n",
        "from functools import cached_property",
        "from typing import TYPE_CHECKING, cast\n",
        *imports,
        "",
        "if TYPE_CHECKING:",
        "    from .._client import AsyncOpencode, Opencode\n",
        '__all__ = ["AsyncResources", "SyncResources"]\n\n',
        "class SyncResources:",
        '    """Resource groups of :class:`opencode.Opencode`."""\n',
        *sync_props,
        "",
        "class AsyncResources:",
        '    """Resource groups of :class:`opencode.AsyncOpencode`."""\n',
        *async_props,
    ]
    return "\n".join(lines).rstrip() + "\n"


# -- api.md -------------------------------------------------------------------------------------------------


def render_api_md(resources: dict[str, Resource], version: str) -> str:
    lines = [
        "# API reference",
        "",
        f"Generated from the OpenCode {version} contract. Every method exists on both `Opencode` and `AsyncOpencode`;",
        "async methods return awaitables, async list methods return `AsyncPaginator`, and async streams return",
        "`AsyncStream`. Types live in `opencode.types`.",
        "",
    ]

    def walk(resource: Resource, attr: str) -> None:
        if resource.operations:
            lines.append(f"## `client.{attr}`")
            lines.append("")
            lines.append("| Method | HTTP | Returns | Summary |")
            lines.append("| --- | --- | --- | --- |")
            for operation in resource.operations:
                returns = operation.return_type
                if operation.kind == "page":
                    returns = f"SyncCursorPage[{returns}]"
                elif operation.kind == "stream":
                    returns = f"Stream[{returns}]"
                summary = (operation.summary or "").replace("|", "\\|")
                if operation.experimental:
                    summary += " *(experimental)*"
                signature = ", ".join(param.name for param in operation.path_params)
                lines.append(
                    f"| `{operation.method_name}({signature})` | `{operation.http_method} {operation.path}` | "
                    f"`{returns.replace('|', '&#124;')}` | {summary} |"
                )
            lines.append("")
        for name, child in resource.children.items():
            walk(child, f"{attr}.{name}")

    for name, resource in sorted(resources.items()):
        walk(resource, name)
    return "\n".join(lines)
